const {useState,useEffect,useRef}=React;
const STAGES=['Ideia','Análise','Planejamento','Desenvolvimento','Testes','Homologação','Aprovação','Publicação','Concluído'];
const TASKS=['Backlog','A fazer','Em desenvolvimento','Em testes','Concluído'];
const TYPES=['Novo sistema','Aplicativo','Plataforma web','Site','Sistema interno','Inteligência Artificial','Automação','Integração entre sistemas','Banco de dados','Dashboard','Solução para Prefeitura','Solução educacional','Solução de segurança','Solução de mobilidade','Solução para eventos','Atualização de sistema existente','Correção de erro','Manutenção','Pesquisa e desenvolvimento'];
const ROLES=['Administrador','Gestor','Programador','Cliente','Visualização'];
const NAV=[['workspace','VISÃO GERAL'],['dashboard','Visão geral','grid'],['projects','Projetos','folder'],['demands','Demandas','inbox'],['tasks','Minhas tarefas','check'],['kanban','Quadro Kanban','kanban'],['calendar','Cronograma','calendar'],['management','GESTÃO & INTELIGÊNCIA'],['executive','Painel executivo','chart'],['assistant','Assistente Skyx','spark'],['documents','Documentação','file'],['team','Equipe & acessos','users'],['operations','OPERAÇÕES'],['monitor','System Monitor','pulse'],['audit','Histórico & auditoria','history'],['settings','Configurações','settings']];
const ICONS={grid:<><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></>,folder:<path d="M3 7V5h6l2 2h10v13H3z"/>,inbox:<><path d="m3 4-1 15h20L21 4z"/><path d="M2 13h6l2 3h4l2-3h6"/></>,check:<><rect x="3" y="3" width="18" height="18" rx="5"/><path d="m7 12 3 3 7-7"/></>,kanban:<><rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8 7v10m4-10v6m4-6v9"/></>,calendar:<><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18m-13 4h3"/></>,chart:<><path d="M4 3v17h17M8 16v-5m5 5V7m5 9V3"/></>,spark:<><path d="m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8zM20 2v4m-2-2h4"/></>,file:<><path d="M5 2h9l5 5v15H5zM14 2v6h5M8 12h8m-8 4h6"/></>,users:<><circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/></>,pulse:<><path d="M2 12h5l3-8 4 16 3-8h5"/></>,history:<><path d="M3 11a9 9 0 1 1 3 8M3 4v7h7m2-5v6l4 2"/></>,settings:<><circle cx="12" cy="12" r="3"/><path d="m9 3 1-1h4l1 3 3 1 3 2-1 4 1 4-3 2-3 1-1 3h-4l-1-3-3-1-3-2 1-4-1-4 3-2 3-1z"/></>,search:<><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></>,bell:<><path d="M5 17V9a7 7 0 0 1 14 0v8l2 2H3zm5 5h4"/></>,arrow:<path d="M5 12h14m-6-6 6 6-6 6"/>,plus:<path d="M12 4v16M4 12h16"/>,close:<path d="m6 6 12 12M6 18 18 6"/>,logout:<><path d="M10 3H3v18h7m4-14 5 5-5 5m-6-5h13"/></>,moon:<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12z"/>,download:<><path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/></>,lock:<><rect x="5" y="10" width="14" height="12" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/></>,dots:<><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></>,menu:<path d="M3 6h18M3 12h18M3 18h18"/>,code:<><path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/></>};
function Icon({name,size=20}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{ICONS[name]||ICONS.folder}</svg>}
const fmt=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'Sem prazo';
const today=()=>new Date().toLocaleDateString('en-CA');
const initials=n=>(n||'Skyx').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const late=p=>p.deadline&&p.deadline<today()&&p.status!=='Concluído';
let csrf='';
async function api(path,method='GET',data){let r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data?JSON.stringify(data):undefined});let j=await r.json();if(!r.ok){if(r.status===401&&path!=='login')window.dispatchEvent(new Event('session-expired'));throw Error(j.error||'Não foi possível concluir.')}return j}
function Badge({children,type}){let t=type||(['Concluído','Online','Baixa'].includes(children)?'green':['Urgente','Offline','Indisponível','Atrasado'].includes(children)?'red':['Testes','Em testes','Alta','Em análise','Aprovação'].includes(children)?'amber':['Desenvolvimento','Em desenvolvimento'].includes(children)?'blue':'purple');return <span className={'badge '+t}><i/>{children}</span>}
function Avatar({name,small=false}){return <span className={'avatar '+(small?'small':'')}>{initials(name)}</span>}
function Empty({title='Tudo pronto para começar',text='Os registros aparecerão aqui assim que forem adicionados.',action}){return <div className="empty"><span><Icon name="folder" size={28}/></span><h3>{title}</h3><p>{text}</p>{action}</div>}
function Progress({value}){return <div className="progress-line"><div className="progress"><i style={{width:(value||0)+'%'}}/></div><span>{value||0}%</span></div>}
function Modal({title,onClose,children,wide=false}){let ref=useRef();useEffect(()=>{let prev=document.activeElement;let el=ref.current;el?.querySelector('input,button,select,textarea')?.focus();function key(e){if(e.key==='Escape')onClose();if(e.key==='Tab'){let els=[...el.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus()}}}document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);prev?.focus()}},[]);return <div className="modal-overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section ref={ref} role="dialog" aria-modal="true" aria-label={title} className={'modal '+(wide?'wide':'')}><header><div><span className="eyebrow">SKYX GESTÃO</span><h2>{title}</h2></div><button className="icon-button" aria-label="Fechar" onClick={onClose}><Icon name="close"/></button></header>{children}</section></div>}
function Auth({onLogin}){let [setup,S]=useState(null),[error,E]=useState(''),[busy,B]=useState(false);useEffect(()=>{api('bootstrap').then(x=>S(x.setupRequired)).catch(e=>E(e.message))},[]);async function submit(e){e.preventDefault();B(true);E('');let b=Object.fromEntries(new FormData(e.target));try{if(setup)await api('setup','POST',{...b,demo:b.demo==='on'});let r=await api('login','POST',b);csrf=r.csrf;onLogin(r.user)}catch(err){E(err.message)}finally{B(false)}}return <div className="auth"><section className="auth-story"><div className="brand"><img src="/favicon.svg"/><strong>skyx<span>gestão</span></strong></div><div><span className="eyebrow">TECHNOLOGY COMMAND CENTER</span><h1>Grandes ideias.<br/>Gestão à altura.</h1><p>Todo o seu ecossistema tecnológico.<br/>Conectado em um só lugar.</p><div className="orbit"><div className="orbit-center"><img src="/favicon.svg"/></div><span className="orbit-tag a"><Icon name="code"/> Desenvolvimento</span><span className="orbit-tag b"><Icon name="check"/> Entregas conectadas</span><span className="orbit-tag c"><Icon name="pulse"/> Visão em tempo real</span></div></div><small>SKY X · Tecnologia que transforma.</small></section><section className="auth-form"><div><span className="eyebrow">BEM-VINDO AO SKYX GESTÃO</span><h2>{setup?'Vamos preparar seu ambiente.':'Seu centro de comando.'}</h2><p>{setup?'Crie o primeiro administrador para começar.':'Entre com sua conta para acompanhar o que vem a seguir.'}</p><form onSubmit={submit}>{setup&&<label>Nome completo<input name="name" autoComplete="name" required placeholder="Seu nome"/></label>}<label>E-mail profissional<input type="email" name="email" required autoComplete="username" placeholder="voce@empresa.com.br"/></label><label>Senha<input type="password" name="password" minLength={setup?12:1} required autoComplete={setup?'new-password':'current-password'} placeholder={setup?'Pelo menos 12 caracteres':'Sua senha'}/></label>{!setup&&<label>Código 2FA <small>se estiver ativado</small><input name="code" inputMode="numeric" maxLength={6} autoComplete="one-time-code" placeholder="000000"/></label>}{setup&&<label className="checkbox"><input type="checkbox" name="demo" defaultChecked/> Incluir projetos de demonstração identificados</label>}{error&&<div role="alert" className="error">{error}</div>}<button className="primary full" disabled={busy||setup===null}>{busy?'Preparando…':setup?'Criar meu ambiente':'Entrar no ambiente'}<Icon name="arrow"/></button></form><div className="secure-note"><Icon name="lock" size={15}/> Acesso individual · Ambiente protegido</div></div><small>Skyx Gestão © {new Date().getFullYear()}</small></section></div>}
function App(){let [user,U]=useState(null),[loading,L]=useState(true),[state,S]=useState(null),[page,P]=useState('dashboard'),[selected,SEL]=useState(null),[tab,TAB]=useState('overview'),[modal,M]=useState(null),[toast,TO]=useState(''),[search,Q]=useState(''),[filter,F]=useState('Todos'),[menu,MENU]=useState(false),[theme,THEME]=useState(localStorage.getItem('skyx-theme')||'light'),[notifications,N]=useState(false),[view,V]=useState('grid');
useEffect(()=>{api('me').then(x=>{csrf=x.csrf;U(x.user)}).catch(()=>{}).finally(()=>L(false));let fn=()=>{U(null);S(null)};window.addEventListener('session-expired',fn);return()=>window.removeEventListener('session-expired',fn)},[]);
useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('skyx-theme',theme)},[theme]);
async function refresh(){try{S(await api('state'))}catch(e){TO(e.message)}}
useEffect(()=>{if(user){refresh();let i=setInterval(refresh,30000);return()=>clearInterval(i)}},[user]);
useEffect(()=>{if(toast){let t=setTimeout(()=>TO(''),4500);return()=>clearTimeout(t)}},[toast]);
function go(p){P(p);SEL(null);F('Todos');Q('');MENU(false);N(false)}
function openProject(p){SEL(p.id);P('projects');TAB('overview')}
async function save(kind,data,id){try{let result=await api(kind+(id?'/'+id:''),id?'PATCH':'POST',data);await refresh();M(null);TO('Alterações salvas com sucesso.');return result}catch(e){throw e}}
async function mutate(path,method='POST',data={}){try{let r=await api(path,method,data);await refresh();TO('Operação concluída.');return r}catch(e){TO(e.message)}}
function remove(kind,item){M({kind:'confirm',title:'Excluir registro?',text:'Esta ação excluirá “'+item.name+'”'+(kind==='projects'?' e seus registros vinculados':'')+'.',action:async()=>{await api(kind+'/'+item.id,'DELETE');if(selected===item.id)SEL(null);await refresh();M(null);TO('Registro excluído.')}})}
if(loading)return <div className="loading"><img src="/favicon.svg"/>Preparando seu centro de comando…</div>;
if(!user)return <Auth onLogin={U}/>;
if(!state)return <div className="loading">Carregando dados…{toast&&<p>{toast}</p>}</div>;
const manager=['Administrador','Gestor'].includes(user.role),writer=manager||user.role==='Programador';
const username=id=>state.users.find(x=>x.id===id)?.name||'Não atribuído';
const project=state.projects.find(x=>x.id===selected);
const projects=state.projects.filter(p=>(filter==='Todos'||p.status===filter)&&JSON.stringify(p).toLowerCase().includes(search.toLowerCase()));
const overdue=state.projects.filter(late),active=state.projects.filter(p=>p.status!=='Concluído');
const due=active.filter(p=>p.deadline&&p.deadline>=today()&&p.deadline<=new Date(Date.now()+7*86400000).toLocaleDateString('en-CA'));
const title=NAV.find(n=>n[0]===page)?.[1]||'Visão geral';
const newButton=(kind,label,extra={})=><button className="primary" onClick={()=>M({kind,...extra})}><Icon name="plus" size={18}/>{label}</button>;
function projectCard(p){return <article className="project-card" key={p.id}><div className="row"><button className={'project-symbol color-'+(state.projects.indexOf(p)%4)} onClick={()=>openProject(p)} aria-label={'Abrir '+p.name}>{p.code||initials(p.name)}</button><Badge>{p.priority||'Média'}</Badge><button className="icon-button push" aria-label={'Detalhes de '+p.name} onClick={()=>openProject(p)}><Icon name="arrow" size={18}/></button></div><button className="project-title" onClick={()=>openProject(p)}>{p.name}</button><p>{p.area||'Tecnologia'} <span>·</span> {p.demo?'Demonstração':'Projeto Skyx'}</p><Badge>{p.status}</Badge><div className="progress-label"><span>Progresso do projeto</span><strong>{p.progress||0}%</strong></div><div className="progress"><i style={{width:(p.progress||0)+'%'}}/></div><footer><div className="row"><Avatar name={username(p.owner)} small/><span>{username(p.owner).split(' ')[0]}</span></div><span className={late(p)?'overdue':''}><Icon name="calendar" size={14}/>{fmt(p.deadline)}</span></footer></article>}
function taskList(tasks){return tasks.length?<div className="task-list">{tasks.map(t=><div className="task-row" key={t.id}><button disabled={!writer} className={'task-check '+(t.status==='Concluído'?'checked':'')} aria-label={'Concluir '+t.name} onClick={()=>mutate('tasks/'+t.id,'PATCH',{status:t.status==='Concluído'?'A fazer':'Concluído'})}>{t.status==='Concluído'?'✓':''}</button><div className="grow"><button className="text-button" onClick={()=>writer&&M({kind:'tasks',item:t})}>{t.name}</button><small>{state.projects.find(p=>p.id===t.projectId)?.name} · {username(t.owner)}</small></div><Badge>{t.status}</Badge><span className={'task-date '+(late(t)?'overdue':'')}>{fmt(t.deadline)}</span>{writer&&<button className="icon-button" aria-label="Editar tarefa" onClick={()=>M({kind:'tasks',item:t})}><Icon name="dots"/></button>}</div>)}</div>:<Empty title="Nenhuma tarefa por aqui"/>}
function overview(){return <><section className="welcome"><div><div className="eyebrow"><span className="live-dot"/> SEU ECOSSISTEMA, CONECTADO</div><h1>Visão geral<span>.</span></h1><p>Olá, {user.name.split(' ')[0]}. Vamos transformar ideias em entregas.</p></div><div className="row"><span className="date-display"><Icon name="calendar" size={16}/>{new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</span>{(writer||user.role==='Cliente')&&newButton('demands','Nova demanda')}</div></section><div className="metrics">{[[active.length,'Projetos ativos','folder','blue'],[state.projects.filter(p=>p.status==='Desenvolvimento').length,'Em desenvolvimento','code','purple'],[state.projects.filter(p=>p.status==='Testes').length,'Em testes','check','amber'],[state.projects.filter(p=>p.status==='Aprovação'||p.status==='Homologação').length,'Aguardando aprovação','history','teal']].map(([n,label,ic,col])=><button className="metric" key={label} onClick={()=>{go('projects');if(label==='Em desenvolvimento')F('Desenvolvimento');if(label==='Em testes')F('Testes')}}><div className="row"><span>{label}</span><span className={'metric-icon '+col}><Icon name={ic}/></span></div><strong>{String(n).padStart(2,'0')}</strong><small><span className="live-dot"/> Atualizado com seu portfólio</small></button>)}</div><div className="dashboard-columns"><div className="main-column"><section className="section-head"><div><h2>Projetos em andamento <span className="count">{active.length}</span></h2><p>Da primeira ideia à próxima grande entrega.</p></div><button className="text-link" onClick={()=>go('projects')}>Ver todos <Icon name="arrow" size={16}/></button></section><div className="project-grid">{active.slice(0,4).map(projectCard)}{!active.length&&<Empty title="Seu próximo projeto começa aqui" action={manager&&newButton('projects','Criar projeto')}/>}</div><section className="panel task-panel"><div className="section-head"><div><h2>Próximas entregas</h2><p>O que precisa da sua atenção.</p></div><button className="text-link" onClick={()=>go('tasks')}>Ver tarefas <Icon name="arrow" size={16}/></button></div>{taskList(state.tasks.filter(t=>t.status!=='Concluído').sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999')).slice(0,4))}</section></div><aside className="right-column"><section className="ai-card"><div className="row"><span className="ai-icon"><Icon name="spark" size={23}/></span><span className="mini-badge">SKYX INTELLIGENCE</span></div><h2>Uma nova perspectiva<br/>para seus projetos.</h2><p>Identifique prioridades, organize ideias e planeje os próximos passos.</p><button onClick={()=>go('assistant')}>Conversar com o assistente <Icon name="arrow" size={17}/></button><small>{state.integrations.ai?'IA conectada ao seu ambiente':'Análise local disponível'}</small></section><section className="panel attention"><div className="section-head"><h2>No radar</h2><Icon name="pulse" size={18}/></div><button onClick={()=>{go('projects')}}><span className="radar-icon red"><Icon name="history"/></span><div><strong>{overdue.length} projeto{overdue.length!==1?'s':''} em atraso</strong><small>Revise os prazos e prioridades</small></div><Icon name="arrow" size={15}/></button><button onClick={()=>go('calendar')}><span className="radar-icon amber"><Icon name="calendar"/></span><div><strong>{due.length} entrega{due.length!==1?'s':''} nesta semana</strong><small>Fique de olho no cronograma</small></div><Icon name="arrow" size={15}/></button><button onClick={()=>go('demands')}><span className="radar-icon blue"><Icon name="inbox"/></span><div><strong>{state.demands.filter(d=>d.status!=='Convertida').length} demandas abertas</strong><small>Novas ideias aguardando análise</small></div><Icon name="arrow" size={15}/></button></section><section className="panel activity"><div className="section-head"><h2>Últimas atividades</h2><span className="live-dot"/></div>{state.audit.slice(0,4).map(a=><div className="activity-item" key={a.id}><Avatar name={a.user_name} small/><div><p><strong>{a.user_name}</strong> {a.action}</p><small>{fmt(a.created)} · {new Date(a.created).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div></div>)}{!state.audit.length&&<p className="muted">As atualizações aparecerão aqui.</p>}<button className="text-link" onClick={()=>go('audit')}>Ver histórico completo <Icon name="arrow" size={15}/></button></section></aside></div></>}
function detail(){let tasks=state.tasks.filter(t=>t.projectId===project.id);return <><button className="text-link back" onClick={()=>SEL(null)}>← Todos os projetos</button><section className="page-heading"><div><div className="row"><span className="eyebrow">{project.area||'TECNOLOGIA'} {project.demo?'· DEMONSTRAÇÃO':''}</span><Badge>{project.status}</Badge></div><h1>{project.name}</h1><p>{project.description}</p></div>{manager&&<div className="row"><button className="secondary" onClick={()=>M({kind:'projects',item:project})}>Editar projeto</button><button className="icon-button danger" aria-label="Excluir projeto" onClick={()=>remove('projects',project)}><Icon name="close"/></button></div>}</section><div className="stage-flow">{STAGES.map((s,i)=><span key={s} className={i<=STAGES.indexOf(project.status)?'passed':''}><i>{i<STAGES.indexOf(project.status)?'✓':i+1}</i>{s}</span>)}</div><div className="tabs">{[['overview','Visão geral'],['tasks','Tarefas'],['milestones','Cronograma'],['comments','Comentários'],['documents','Documentação'],['versions','Versões'],['environments','Acesso ao sistema']].map(([k,l])=><button className={tab===k?'active':''} onClick={()=>TAB(k)} key={k}>{l}{k==='tasks'&&<span>{tasks.length}</span>}</button>)}</div>{user.role==='Programador'&&<form className="panel padded progress-editor" onSubmit={async e=>{e.preventDefault();try{await save('projects',Object.fromEntries(new FormData(e.target)),project.id)}catch(err){TO(err.message)}}}><label>Estágio<select name="status" defaultValue={project.status}>{STAGES.map(x=><option key={x}>{x}</option>)}</select></label><label>Progresso (%)<input name="progress" type="number" min="0" max="100" defaultValue={project.progress}/></label><label>Próxima etapa<input name="nextStep" defaultValue={project.nextStep}/></label><button className="primary">Atualizar andamento</button></form>}{tab==='overview'?<div className="detail-grid"><section className="panel padded"><h2>Informações do projeto</h2><p>{project.objective||'Adicione o objetivo na edição do projeto.'}</p><div className="info-grid">{[['Responsável técnico',username(project.owner)],['Prioridade',project.priority],['Data de início',fmt(project.start)],['Previsão de término',fmt(project.deadline)],['Última atualização',fmt(project.updatedAt)],['Próxima etapa',project.nextStep||'Não definida']].map(([k,v])=><div key={k}><small>{k}</small><strong>{v}</strong></div>)}</div><h3>Equipe envolvida</h3><div className="row wrap">{(project.team||[]).map(id=><div className="team-chip" key={id}><Avatar name={username(id)} small/>{username(id)}</div>)}</div></section><section className="panel padded"><h2>Progresso da entrega</h2><div className="progress-ring" style={{'--progress':(project.progress||0)*3.6+'deg'}}><div><strong>{project.progress||0}%</strong><small>concluído</small></div></div><Progress value={tasks.length?Math.round(tasks.filter(t=>t.status==='Concluído').length/tasks.length*100):0}/><p className="muted">{tasks.filter(t=>t.status==='Concluído').length} de {tasks.length} tarefas concluídas</p><Badge>{late(project)?'Atrasado':project.status}</Badge></section></div>:tab==='tasks'?<section className="panel padded"><div className="section-head"><h2>Tarefas do projeto</h2>{writer&&newButton('tasks','Nova tarefa',{projectId:project.id})}</div>{taskList(tasks)}</section>:tab==='comments'?<section className="panel padded"><h2>Conversa do projeto</h2>{user.role!=='Visualização'&&<form className="comment-form" onSubmit={async e=>{e.preventDefault();let form=e.target;try{await save('comments',{name:form.comment.value,projectId:project.id,type:form.type.value});form.reset()}catch(err){TO(err.message)}}}><textarea name="comment" required maxLength={200} placeholder="Compartilhe uma orientação, feedback ou atualização…"/><div className="row"><select name="type">{['Comentário','Orientação','Pendência','Alteração','Feedback','Aprovação'].map(x=><option key={x}>{x}</option>)}</select><button className="primary push">Enviar comentário</button></div></form>}{state.comments.filter(c=>c.projectId===project.id).map(c=><div className="comment" key={c.id}><Avatar name={username(c.authorId)}/><div><strong>{username(c.authorId)}</strong><small>{fmt(c.createdAt)} · {c.type}</small><p>{c.name}</p></div></div>)}</section>:tab==='environments'?<><section className="section-head"><h2>Ambientes e acessos</h2>{manager&&newButton('environments','Adicionar ambiente',{projectId:project.id})}</section><div className="cards-grid">{state.environments.filter(e=>e.projectId===project.id).map(e=><section className="panel padded" key={e.id}><div className="row"><h3>{e.name}</h3><Badge>{e.serverStatus||'Não verificado'}</Badge></div><p>{e.environment} · {e.version||'Sem versão'}</p><a className="text-link" href={e.url} target="_blank" rel="noopener noreferrer">Abrir sistema <Icon name="arrow" size={15}/></a><small className="block">Verificado: {e.checkedAt?fmt(e.checkedAt):'ainda não verificado'}</small>{manager&&<button className="secondary" onClick={()=>M({kind:'environments',item:e})}>Editar ambiente</button>}</section>)}</div><section className="panel padded space-top"><div className="section-head"><div><h2>Cofre de credenciais</h2><p>Senhas criptografadas. Toda consulta é auditada.</p></div>{manager&&newButton('credentials','Adicionar credencial',{projectId:project.id})}</div>{state.credentials.filter(e=>e.projectId===project.id).map(e=><div className="task-row" key={e.id}><Icon name="lock"/><div className="grow"><strong>{e.name}</strong><small>Usuário: {e.username}</small></div>{writer&&<button className="secondary" onClick={async()=>{let r=await mutate('credentials/'+e.id+'/reveal');if(r)M({kind:'secret',title:e.name,secret:r.secret})}}>Consultar senha</button>}</div>)}{!writer&&<p>Credenciais disponíveis somente para a equipe técnica autorizada.</p>}</section></>:tab==='milestones'?<section className="panel padded"><div className="section-head"><h2>Linha do tempo</h2>{writer&&newButton('milestones','Adicionar etapa',{projectId:project.id})}</div><div className="timeline">{state.milestones.filter(m=>m.projectId===project.id).sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(m=><div key={m.id}><button disabled={!writer} className={m.done?'done':''} onClick={()=>mutate('milestones/'+m.id,'PATCH',{done:!m.done})}>{m.done?'✓':'○'}</button><span>{fmt(m.date)}</span><strong>{m.name}</strong>{writer&&<button className="text-link" onClick={()=>M({kind:'milestones',item:m})}>Editar</button>}</div>)}</div></section>:collection(tab,project.id)}</>}
function collection(kind,pid){let rows=state[kind].filter(x=>(!pid||x.projectId===pid)&&JSON.stringify(x).toLowerCase().includes(search.toLowerCase()));return <section className="panel padded"><div className="section-head"><div><h2>{kind==='documents'?'Biblioteca de documentos':'Histórico de versões'}</h2><p>{kind==='documents'?'O conhecimento do projeto, sempre por perto.':'Registre entregas, commits e alterações.'}</p></div>{writer&&newButton(kind,kind==='documents'?'Enviar arquivo':'Nova versão',{projectId:pid})}</div>{rows.length?<div className="table-wrap"><table><thead><tr><th>{kind==='documents'?'Documento':'Versão'}</th><th>Projeto</th><th>{kind==='documents'?'Categoria':'Branch / commit'}</th><th>Atualizado</th><th>Ações</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><div className="row"><span className="file-icon"><Icon name={kind==='documents'?'file':'code'}/></span><div><strong>{r.name}</strong><small>{kind==='documents'?Math.ceil(r.size/1024)+' KB':r.changelog}</small></div></div></td><td>{state.projects.find(p=>p.id===r.projectId)?.name}</td><td>{r.category||r.branch} {r.commit}</td><td>{fmt(r.updatedAt)}</td><td><div className="row">{kind==='documents'&&<a className="icon-button" title="Baixar arquivo" href={'/api/documents/'+r.id+'/download'}><Icon name="download"/></a>}{writer&&<button className="icon-button danger" aria-label={'Excluir '+r.name} onClick={()=>remove(kind,r)}><Icon name="close" size={16}/></button>}</div></td></tr>)}</tbody></table></div>:<Empty title={kind==='documents'?'Uma biblioteca pronta para receber conhecimento':'Nenhuma versão registrada'}/>}</section>}
function content(){if(project)return detail();if(page==='dashboard')return overview();return <><section className="page-heading"><div><span className="eyebrow">SEU CENTRO DE COMANDO</span><h1>{title}<span>.</span></h1><p>{{projects:'Cada projeto, uma nova possibilidade. Acompanhe cada etapa.',demands:'Transforme necessidades em soluções tecnológicas.',tasks:'Organize prioridades e mantenha as entregas em movimento.',kanban:'Visualize o fluxo de trabalho da sua equipe.',calendar:'Todas as etapas, conectadas em uma linha do tempo.',executive:'Uma visão estratégica do seu ecossistema.',assistant:'Clareza para decidir. Inteligência para avançar.',documents:'Conhecimento centralizado, colaboração simplificada.',team:'As pessoas que fazem a tecnologia acontecer.',monitor:'Visibilidade sobre seus ambientes e serviços.',audit:'Cada alteração conta uma parte da história.',settings:'Seu ambiente, suas preferências.'}[page]}</p></div>{page==='projects'&&manager&&newButton('projects','Novo projeto')}{page==='demands'&&(writer||user.role==='Cliente')&&newButton('demands','Nova demanda')}{['tasks','kanban'].includes(page)&&writer&&newButton('tasks','Nova tarefa')}{page==='team'&&user.role==='Administrador'&&newButton('users','Adicionar pessoa')}</section>{page==='projects'?<><div className="toolbar"><div className="filter-pills">{['Todos','Desenvolvimento','Testes','Homologação','Concluído'].map(s=><button className={filter===s?'active':''} onClick={()=>F(s)} key={s}>{s}</button>)}</div><div className="row"><button className={'icon-button '+(view==='grid'?'selected':'')} onClick={()=>V('grid')} aria-label="Visualização em cards"><Icon name="grid"/></button><button className={'icon-button '+(view==='list'?'selected':'')} onClick={()=>V('list')} aria-label="Visualização em lista"><Icon name="menu"/></button></div></div>{view==='grid'?<div className="all-projects">{projects.map(projectCard)}</div>:<section className="panel table-wrap"><table><thead><tr><th>Projeto</th><th>Responsável</th><th>Status</th><th>Progresso</th><th>Prazo</th></tr></thead><tbody>{projects.map(p=><tr key={p.id}><td><button className="text-button" onClick={()=>openProject(p)}>{p.name}</button></td><td>{username(p.owner)}</td><td><Badge>{p.status}</Badge></td><td><Progress value={p.progress}/></td><td className={late(p)?'overdue':''}>{fmt(p.deadline)}</td></tr>)}</tbody></table></section>}{!projects.length&&<Empty title="Nenhum projeto encontrado"/>}</>:page==='demands'?<section className="panel table-wrap"><table><thead><tr><th>Demanda</th><th>Área</th><th>Prioridade</th><th>Status</th><th>Prazo</th><th>Ações</th></tr></thead><tbody>{state.demands.filter(d=>JSON.stringify(d).toLowerCase().includes(search.toLowerCase())).map(d=><tr key={d.id}><td><button className="text-button" onClick={()=>M({kind:'demands',item:d,readOnly:!manager})}>{d.name}</button><small>{d.type}</small></td><td>{d.area||'—'}</td><td><Badge>{d.priority}</Badge></td><td><Badge>{d.status||'Nova'}</Badge></td><td>{fmt(d.deadline)}</td><td>{manager&&d.status!=='Convertida'&&<button className="secondary" onClick={()=>M({kind:'projects',demand:d})}>Criar projeto <Icon name="arrow" size={14}/></button>}</td></tr>)}</tbody></table>{!state.demands.length&&<Empty title="Qual é a próxima grande ideia?"/>}</section>:page==='tasks'?<><div className="toolbar"><div className="filter-pills">{['Todos','Minhas tarefas','Atrasadas','Concluídas'].map(x=><button className={filter===x?'active':''} onClick={()=>F(x)} key={x}>{x}</button>)}</div></div><section className="panel padded">{taskList(state.tasks.filter(t=>(filter!=='Minhas tarefas'||t.owner===user.id)&&(filter!=='Atrasadas'||late(t))&&(filter!=='Concluídas'||t.status==='Concluído')&&JSON.stringify(t).toLowerCase().includes(search.toLowerCase())))}</section></>:page==='kanban'?<div className="kanban">{TASKS.map((status,i)=><section className="kanban-column" key={status} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();let id=e.dataTransfer.getData('text/plain');if(writer&&state.tasks.some(t=>t.id===id))mutate('tasks/'+id,'PATCH',{status})}}><header><i className={'column-dot dot-'+i}/><h3>{status}</h3><span className="count">{state.tasks.filter(t=>t.status===status).length}</span></header>{state.tasks.filter(t=>t.status===status&&JSON.stringify(t).toLowerCase().includes(search.toLowerCase())).map(t=><article draggable={writer} onDragStart={e=>e.dataTransfer.setData('text/plain',t.id)} className="kanban-card" key={t.id}><small>{state.projects.find(p=>p.id===t.projectId)?.name}</small><button className="text-button" onClick={()=>writer&&M({kind:'tasks',item:t})}>{t.name}</button><Badge>{t.priority}</Badge><footer><Avatar small name={username(t.owner)}/><span className={late(t)?'overdue':''}>{fmt(t.deadline)}</span></footer>{writer&&<select aria-label={'Mover '+t.name} value={t.status} onChange={e=>mutate('tasks/'+t.id,'PATCH',{status:e.target.value})}>{TASKS.map(x=><option key={x}>{x}</option>)}</select>}</article>)}{writer&&<button className="kanban-add" onClick={()=>M({kind:'tasks',status})}>+ Adicionar tarefa</button>}</section>)}</div>:page==='calendar'?<section className="panel padded"><div className="section-head"><h2>Cronograma geral</h2><span className="muted">Ordenado por previsão de entrega</span></div>{[...state.projects].sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999')).map(p=><div className="schedule-row" key={p.id}><div className={'schedule-date '+(late(p)?'overdue':'')}><strong>{p.deadline?new Date(p.deadline+'T12:00:00').getDate():'—'}</strong><small>{p.deadline?new Date(p.deadline+'T12:00:00').toLocaleDateString('pt-BR',{month:'short'}):'Sem prazo'}</small></div><div className="grow"><button className="text-button" onClick={()=>openProject(p)}>{p.name}</button><small>{fmt(p.start)} → {fmt(p.deadline)} · {username(p.owner)}</small><Progress value={p.progress}/></div><Badge>{late(p)?'Atrasado':p.status}</Badge></div>)}</section>:page==='documents'?collection('documents'):page==='executive'?<Executive state={state} username={username}/>:page==='assistant'?<Assistant state={state} projects={state.projects} save={save} notify={TO} writer={writer}/>:page==='team'?<div className="cards-grid">{state.users.map(u=><section className="panel person-card" key={u.id}><Avatar name={u.name}/><h3>{u.name}</h3><p>{u.email||u.role}</p><Badge>{u.role}</Badge><div className="person-stats"><span><strong>{state.projects.filter(p=>p.owner===u.id||(p.team||[]).includes(u.id)).length}</strong>projetos</span><span><strong>{state.tasks.filter(t=>t.owner===u.id&&t.status!=='Concluído').length}</strong>tarefas abertas</span></div>{!u.active&&<Badge type="red">Acesso desativado</Badge>}{user.role==='Administrador'&&u.id!==user.id&&<button className="secondary full" onClick={()=>M({kind:'users',item:u})}>Gerenciar acesso</button>}</section>)}</div>:page==='monitor'?<><div className="notice"><Icon name="pulse"/><div><strong>Monitoramento sob demanda</strong><p>Cadastre os ambientes dentro dos projetos e autorize os domínios no servidor. O status representa a última verificação HTTP, não a disponibilidade contínua.</p></div></div><div className="cards-grid">{state.environments.map(e=><section className="panel padded" key={e.id}><div className="row"><span className="file-icon"><Icon name="pulse"/></span><Badge>{e.serverStatus||'Não verificado'}</Badge></div><h3>{e.name}</h3><p>{state.projects.find(p=>p.id===e.projectId)?.name}</p><small className="block">{e.url}</small><div className="info-grid"><div><small>Ambiente</small><strong>{e.environment}</strong></div><div><small>Resposta</small><strong>{e.latency?e.latency+' ms':'—'}</strong></div></div><p>Última consulta: {e.checkedAt?new Date(e.checkedAt).toLocaleString('pt-BR'):'Sem verificação'}</p>{manager&&<button className="secondary full" onClick={()=>mutate('monitor/'+e.id)}>Verificar agora</button>}</section>)}</div>{!state.environments.length&&<Empty title="Conecte seu primeiro ambiente" text="Abra um projeto e adicione um ambiente em Acesso ao sistema." action={<button className="primary" onClick={()=>go('projects')}>Ir para projetos</button>}/>}</>:page==='audit'?<section className="panel table-wrap"><table><thead><tr><th>Data e hora</th><th>Usuário</th><th>Atividade</th><th>Origem IP</th></tr></thead><tbody>{state.audit.filter(a=>JSON.stringify(a).toLowerCase().includes(search.toLowerCase())).map(a=><tr key={a.id}><td>{new Date(a.created).toLocaleString('pt-BR')}</td><td><div className="row"><Avatar name={a.user_name} small/>{a.user_name}</div></td><td>{a.action}</td><td><code>{a.ip}</code></td></tr>)}</tbody></table></section>:page==='settings'?<Settings user={user} theme={theme} setTheme={THEME} notify={TO} onUser={U}/>:null}</>}
return <div className="app-shell"><aside className={'sidebar '+(menu?'open':'')}><button className="brand" onClick={()=>go('dashboard')}><img src="/favicon.svg"/><strong>skyx<span>gestão</span></strong><span className="brand-label">WORKSPACE</span></button><div className="workspace"><span className="workspace-symbol">S</span><div><strong>Sky X Tecnologia</strong><small>Centro de desenvolvimento</small></div><span>⌄</span></div><nav>{NAV.map(([id,label,icon])=>!icon?<div className="nav-label" key={id}>{label}</div>:<button key={id} className={page===id?'active':''} onClick={()=>go(id)}><Icon name={icon} size={18}/><span>{label}</span>{id==='demands'&&state.demands.length>0&&<em>{state.demands.length}</em>}{id==='assistant'&&<span className="nav-ai">IA</span>}</button>)}</nav><div className="sidebar-bottom"><div className="connection"><span className="live-dot"/><span>Ambiente conectado</span><small>v1.0</small></div><div className="sidebar-profile"><Avatar name={user.name}/><div><strong>{user.name}</strong><small>{user.role}</small></div><button className="icon-button" title="Sair" onClick={async()=>{await api('logout','POST');U(null);S(null)}}><Icon name="logout" size={18}/></button></div></div></aside>{menu&&<div className="sidebar-scrim" onClick={()=>MENU(false)}/>}<div className="app-body"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="Abrir menu" onClick={()=>MENU(!menu)}><Icon name="menu"/></button><Icon name="grid" size={16}/><span>Workspace</span><b>/</b><strong>{title}</strong></div><div className="top-actions"><label className="global-search"><Icon name="search" size={17}/><input aria-label="Buscar na página" placeholder="Buscar nesta página…" value={search} onChange={e=>Q(e.target.value)}/><kbd>⌕</kbd></label><button className="icon-button" aria-label="Alternar tema" onClick={()=>THEME(theme==='light'?'dark':'light')}><Icon name="moon" size={19}/></button><button className="icon-button notification-button" aria-label="Notificações" onClick={()=>N(!notifications)}><Icon name="bell" size={19}/>{state.notifications.some(n=>!n.read)&&<i/>}</button><span className="top-divider"/><Avatar name={user.name} small/></div></header><main>{content()}<footer className="page-footer"><span>SKYX GESTÃO <b>·</b> Tecnologia conectada. Gestão inteligente.</span><span><span className="live-dot"/> Sincronizado a cada 30s</span></footer></main></div>{notifications&&<section className="notification-panel"><div className="section-head"><h2>Notificações</h2><button className="text-link" onClick={()=>mutate('notifications/read')}>Marcar como lidas</button></div>{state.notifications.length?state.notifications.map(n=><button key={n.id} className={'notification '+(!n.read?'unread':'')} onClick={()=>{let p=state.projects.find(p=>p.id===n.project_id);if(p){openProject(p);N(false)}}}><span className="file-icon"><Icon name="bell" size={17}/></span><div><strong>{n.title}</strong><small>{fmt(n.created)}</small></div></button>):<Empty title="Você está em dia"/>}</section>}{toast&&<div className="toast" role="status"><Icon name="check" size={18}/>{toast}<button aria-label="Fechar aviso" onClick={()=>TO('')}>×</button></div>}{modal&&(modal.kind==='confirm'?<Confirm modal={modal} close={()=>M(null)}/>:modal.kind==='secret'?<Modal title={modal.title} onClose={()=>M(null)}><div className="padded"><p>Credencial de teste. Esta consulta foi registrada na auditoria.</p><code className="secret">{modal.secret}</code><button className="primary" onClick={()=>M(null)}>Fechar credencial</button></div></Modal>:<RecordForm config={modal} state={state} user={user} save={save} close={()=>M(null)} notify={TO}/>)}</div>}
function Confirm({modal,close}){let [busy,B]=useState(false),[error,E]=useState('');return <Modal title={modal.title} onClose={close}><div className="padded"><p>{modal.text}</p>{error&&<p className="error">{error}</p>}<div className="form-actions"><button className="secondary" onClick={close}>Cancelar</button><button className="danger-button" disabled={busy} onClick={async()=>{B(true);try{await modal.action()}catch(e){E(e.message)}finally{B(false)}}}>Excluir registro</button></div></div></Modal>}
function RecordForm({config,state,user,save,close,notify}){let {kind,item,projectId,demand,readOnly}=config;let [error,E]=useState(''),[busy,B]=useState(false);let defaults=item||demand||{};const labels={projects:'projeto',demands:'demanda',tasks:'tarefa',documents:'documento',versions:'versão',environments:'ambiente',credentials:'credencial',milestones:'etapa',users:'pessoa'};const field=(name,label,type='text',opts={})=><label className={opts.full?'span-2':''} key={name}>{label}{type==='select'?<select name={name} defaultValue={defaults[name]??opts.value??''} required={opts.required!==false} disabled={readOnly}>{(opts.options||[]).map(v=><option key={typeof v==='string'?v:v.id} value={typeof v==='string'?v:v.id}>{typeof v==='string'?v:v.name}</option>)}</select>:type==='textarea'?<textarea name={name} defaultValue={defaults[name]||''} required={!!opts.required} disabled={readOnly} rows={3}/>:<input name={name} type={type} defaultValue={type==='password'?undefined:defaults[name]??opts.value??''} required={!!opts.required} min={opts.min} max={opts.max} minLength={opts.minLength} disabled={readOnly} placeholder={opts.placeholder}/>}</label>;
async function submit(e){e.preventDefault();B(true);E('');try{let fd=new FormData(e.target),data=Object.fromEntries(fd);if(['projects','users'].includes(kind))data[kind==='projects'?'team':'projects']=fd.getAll(kind==='projects'?'team':'projects');if(kind==='projects'){data.progress=Number(data.progress);if(demand)data.demandId=demand.id;}if(kind==='tasks'){data.progress=Number(data.progress);data.estimatedHours=Number(data.estimatedHours)}if(kind==='milestones')data.done=fd.get('done')==='on';if(kind==='users'&&item)data.active=fd.get('active')==='on';if(kind==='documents'){let file=fd.get('file');if(!file?.size)throw Error('Selecione um arquivo.');if(file.size>8000000)throw Error('Limite de 8 MB por arquivo.');data.content=await new Promise((res,rej)=>{let reader=new FileReader();reader.onload=()=>res(reader.result.split(',')[1]);reader.onerror=rej;reader.readAsDataURL(file)});data.name=file.name;data.mime=file.type;delete data.file}if(['demands','tasks'].includes(kind)){data.newAttachments=[];for(const file of fd.getAll('attachments')){if(!file.size)continue;if(file.size>8000000)throw Error('Limite de 8 MB por anexo.');const content=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result.split(',')[1]);reader.onerror=rej;reader.readAsDataURL(file)});data.newAttachments.push({name:file.name,content})}delete data.attachments}if(projectId)data.projectId=projectId;await save(kind,data,item?.id)}catch(err){E(err.message)}finally{B(false)}}
return <Modal title={(readOnly?'Detalhes da ':item?'Editar ':'Adicionar ')+labels[kind]} onClose={close} wide={['projects','demands','tasks','users'].includes(kind)}><form onSubmit={submit} className="record-form"><div className="form-grid">{kind!=='documents'&&field('name',kind==='users'?'Nome completo':'Nome / título','text',{full:true,required:true})}{!['projects','demands','users'].includes(kind)&&!projectId&&field('projectId','Projeto','select',{value:defaults.projectId,full:true,options:[{id:'',name:'Selecione um projeto'},...state.projects]})}{['projects','demands','tasks'].includes(kind)&&field('description','Descrição detalhada','textarea',{full:true})}{['projects','demands'].includes(kind)&&field('objective','Objetivo da solução','textarea',{full:true})}{kind==='demands'&&<>{field('problem','Problema a solucionar','textarea',{full:true})}{field('type','Tipo de solução','select',{options:TYPES,value:'Novo sistema'})}{field('status','Status','select',{options:['Nova','Em análise','Aprovada','Rejeitada','Convertida'],value:'Nova'})}</>}{['projects','demands'].includes(kind)&&field('area','Área solicitante','text',{required:true})}{['projects','demands','tasks'].includes(kind)&&field('priority','Prioridade','select',{options:['Baixa','Média','Alta','Urgente'],value:'Média'})}{['projects','tasks'].includes(kind)&&<>{field('status','Estágio atual','select',{options:kind==='projects'?STAGES:TASKS,value:config.status||(kind==='projects'?'Ideia':'Backlog')})}{field('owner','Responsável','select',{options:[{id:'',name:'Não atribuído'},...state.users.filter(u=>u.active)],value:user.id})}{field('progress','Conclusão (%)','number',{min:0,max:100,value:0})}</>}{kind==='projects'&&field('start','Data de início','date',{value:today()})}{['projects','demands','tasks'].includes(kind)&&field('deadline','Prazo desejado','date')}{kind==='projects'&&<>{field('nextStep','Próxima etapa','text',{full:true})}<label className="span-2">Equipe do projeto<select multiple name="team" defaultValue={defaults.team||[user.id]}>{state.users.filter(u=>u.active).map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select><small>Use Ctrl para selecionar mais de uma pessoa.</small></label></>}{kind==='demands'&&<>{field('requester','Solicitante','select',{options:state.users,value:user.id})}{field('references','Referências (links)','textarea',{full:true})}{field('notes','Observações adicionais','textarea',{full:true})}<p className="field-help span-2">Os anexos também serão incluídos na biblioteca ao converter esta demanda em projeto.</p></>}{['demands','tasks'].includes(kind)&&<div className="span-2">{!readOnly&&<label>Anexos, imagens e documentos<input type="file" name="attachments" multiple/><small>Até 8 MB por arquivo; até 20 anexos por registro.</small></label>}{(defaults.attachments||[]).map(a=><a className="attachment-link" href={'/api/'+kind+'/'+item.id+'/attachments/'+a.id} key={a.id}><Icon name="file" size={16}/>{a.name}<small>{Math.ceil(a.size/1024)} KB</small><Icon name="download" size={15}/></a>)}</div>}{kind==='tasks'&&<>{field('estimatedHours','Esforço estimado (horas)','number',{min:0,value:0})}{field('notes','Comentários técnicos','textarea',{full:true})}</>}{kind==='documents'&&<><label className="span-2 upload-field"><Icon name="file" size={30}/><strong>Selecione o arquivo do projeto</strong><span>Documentos, imagens, diagramas ou vídeos · Até 8 MB</span><input type="file" name="file" required/></label>{field('category','Categoria','select',{options:['Documentação técnica','Manual','Diagrama','Protótipo','Contrato','Briefing','Requisitos','Imagem','Vídeo','Configuração','Documentação de API'],full:true})}</>}{kind==='versions'&&<>{field('branch','Branch principal','text',{value:'main'})}{field('commit','Último commit')}{field('environment','Ambiente','select',{options:['Desenvolvimento','Homologação','Produção']})}{field('changelog','Changelog','textarea',{full:true,required:true})}</>}{kind==='environments'&&<>{field('url','URL do sistema','url',{required:true,full:true})}{field('environment','Ambiente','select',{options:['Desenvolvimento','Homologação','Produção']})}{field('version','Versão atual','text',{placeholder:'v1.0.0'})}</>}{kind==='credentials'&&<>{field('username','Usuário de teste','text',{required:true,full:true})}{field('secret','Senha de teste','password',{required:!item,full:true})}</>}{kind==='milestones'&&<>{field('date','Data prevista','date',{required:true})}<label className="checkbox"><input type="checkbox" name="done" defaultChecked={defaults.done}/> Etapa concluída</label></>}{kind==='users'&&<>{!item&&field('email','E-mail profissional','email',{required:true})}{field('role','Perfil de acesso','select',{options:ROLES,value:'Programador'})}{field('password',item?'Nova senha (opcional)':'Senha inicial','password',{required:!item,minLength:12,full:true,placeholder:'Pelo menos 12 caracteres'})}<label className="span-2">Projetos autorizados<select multiple name="projects" defaultValue={defaults.projects||[]}>{state.projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><small>Programadores, clientes e visualizadores acessam somente projetos autorizados.</small></label>{item&&<label className="checkbox"><input type="checkbox" name="active" defaultChecked={!!item.active}/> Acesso ativo</label>}</>}</div>{error&&<div className="error" role="alert">{error}</div>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>{readOnly?'Fechar':'Cancelar'}</button>{!readOnly&&<button className="primary" disabled={busy}>{busy?'Salvando…':item?'Salvar alterações':kind==='documents'?'Enviar documento':'Salvar '+labels[kind]}</button>}</div></form></Modal>}
function Executive({state,username}){let total=state.projects.length,completed=state.projects.filter(p=>p.status==='Concluído').length;function exportCSV(){let cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';let csv='\ufeff'+[['Projeto','Área','Responsável','Status','Progresso','Prazo'],...state.projects.map(p=>[p.name,p.area,username(p.owner),p.status,p.progress,p.deadline])].map(r=>r.map(cell).join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='skyx-relatorio.csv';a.click();URL.revokeObjectURL(url)}return <><div className="row report-actions"><button className="secondary" onClick={exportCSV}><Icon name="download" size={17}/>Exportar CSV</button><button className="secondary" onClick={()=>window.print()}>Imprimir / salvar PDF</button></div><div className="metrics">{[[total,'Total de projetos'],[completed,'Projetos concluídos'],[state.projects.filter(late).length,'Projetos em atraso'],[Math.round(completed/(total||1)*100)+'%','Taxa de conclusão']].map(([v,l])=><div className="metric" key={l}><span>{l}</span><strong>{v}</strong><small>Indicador calculado do portfólio</small></div>)}</div><div className="detail-grid"><section className="panel padded"><h2>Distribuição por etapa</h2><p>O fluxo do seu ecossistema tecnológico.</p>{STAGES.map(s=><div className="bar-row" key={s}><span>{s}</span><div className="progress"><i style={{width:state.projects.filter(p=>p.status===s).length/(total||1)*100+'%'}}/></div><strong>{state.projects.filter(p=>p.status===s).length}</strong></div>)}</section><section className="panel padded"><h2>Capacidade da equipe</h2><p>Esforço estimado das tarefas ainda em aberto.</p>{state.users.filter(u=>['Administrador','Gestor','Programador'].includes(u.role)).map(u=>{let tasks=state.tasks.filter(t=>t.owner===u.id&&t.status!=='Concluído'),hours=tasks.reduce((a,t)=>a+Number(t.estimatedHours||0),0);return <div className="capacity" key={u.id}><div className="row"><Avatar name={u.name} small/><strong>{u.name}</strong><span className="push">{hours} h</span></div><Progress value={Math.min(100,Math.round(hours/40*100))}/><small>{tasks.length} tarefas · Referência de capacidade: 40 h {hours>40?'· Acima da referência':''}</small></div>})}</section></div><section className="panel padded space-top"><h2>Projetos por área</h2><div className="area-stats">{[...new Set(state.projects.map(p=>p.area||'Tecnologia'))].map(area=><div key={area}><strong>{state.projects.filter(p=>(p.area||'Tecnologia')===area).length}</strong><span>{area}</span></div>)}</div></section></>}
function Assistant({state,projects,save,notify,writer}){let [messages,M]=useState([]),[prompt,P]=useState(''),[busy,B]=useState(false),[pid,PID]=useState('');async function ask(e){e?.preventDefault();if(!prompt.trim()||busy)return;let text=prompt;P('');M(m=>[...m,{role:'user',text}]);B(true);try{let r=await api('assistant','POST',{prompt:text});M(m=>[...m,{role:'assistant',text:r.answer,mode:r.mode}])}catch(e){notify(e.message)}finally{B(false)}}return <section className="assistant-layout"><div className="panel assistant-main"><div className="assistant-header"><span className="ai-icon"><Icon name="spark"/></span><div><h2>Assistente Skyx</h2><small>{state.integrations.ai?'IA conectada':'Análise local por regras · Provedor generativo não configurado'}</small></div></div><div className="chat-content">{!messages.length?<div className="assistant-empty"><div className="large-spark"><Icon name="spark" size={36}/></div><span className="eyebrow">DA IDEIA AO PRÓXIMO PASSO</span><h2>O que vamos construir hoje?</h2><p>Explore o portfólio, revise prioridades ou comece a estruturar uma nova solução.</p><div className="prompt-grid">{['Resuma o andamento dos projetos','Quais tarefas precisam de atenção?','Estruture um sistema de ocorrências','Sugira um plano de entrega'].map(t=><button key={t} onClick={()=>P(t)}>{t}<Icon name="arrow" size={16}/></button>)}</div></div>:messages.map((m,i)=><div className={'chat-message '+m.role} key={i}><strong>{m.role==='user'?'Você':m.mode}</strong><p>{m.text}</p></div>)}{busy&&<p className="muted">Analisando o contexto autorizado…</p>}</div><form onSubmit={ask} className="chat-input"><textarea aria-label="Mensagem ao assistente" value={prompt} onChange={e=>P(e.target.value)} placeholder="Descreva sua ideia ou pergunte sobre os projetos…" required/><button className="primary" disabled={busy||!writer} aria-label="Enviar mensagem"><Icon name="arrow"/></button></form></div><aside className="panel padded assistant-tools"><h3>Do plano à execução</h3><p>Crie um checklist inicial revisável em um projeto.</p><label>Projeto de destino<select value={pid} onChange={e=>PID(e.target.value)}><option value="">Selecione um projeto</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><button className="secondary full" disabled={!pid||busy||!writer} onClick={async()=>{B(true);try{for(let name of ['Validar requisitos e critérios de aceite','Elaborar arquitetura e protótipo','Implementar módulos da solução','Realizar testes e homologação','Preparar publicação e documentação'])await save('tasks',{name,projectId:pid,status:'Backlog',priority:'Média',progress:0,estimatedHours:0});notify('Checklist criado. Revise os responsáveis e os prazos.')}catch(e){notify(e.message)}finally{B(false)}}}>Criar 5 tarefas iniciais</button><small>Modelo padrão por regras. Revise a adequação antes de iniciar o desenvolvimento.</small></aside></section>}
function Settings({user,theme,setTheme,notify,onUser}){let [security,S]=useState(null),[secret,SEC]=useState(''),[busy,B]=useState(false);async function load(){try{S(await api('security'))}catch(e){notify(e.message)}}useEffect(()=>{load()},[]);async function act(data){B(true);try{let r=await api('security','POST',data);if(r.secret)SEC(r.secret);await load();let me=await api('me');onUser(me.user);notify('Configuração atualizada.');return true}catch(e){notify(e.message);return false}finally{B(false)}}return <div className="settings-grid"><section className="panel padded"><h2>Aparência</h2><p>Escolha o tema do seu ambiente.</p><div className="theme-options">{['light','dark'].map(t=><button className={theme===t?'selected':''} key={t} onClick={()=>setTheme(t)}><span className={'theme-preview '+t}><i/><i/><i/></span>{t==='light'?'Claro':'Escuro'} {theme===t?'✓':''}</button>)}</div></section><section className="panel padded"><div className="section-head"><h2>Autenticação em dois fatores</h2><Icon name="lock"/></div><p>Adicione uma segunda camada de proteção com um aplicativo autenticador.</p><Badge type={security?.twoFactor?'green':'amber'}>{security?.twoFactor?'2FA ativado':'2FA não ativado'}</Badge>{!security?.twoFactor&&!secret&&<button className="secondary block space-top" disabled={busy} onClick={()=>act({action:'setup2fa'})}>Configurar autenticador</button>}{secret&&!security?.twoFactor&&<form className="space-top" onSubmit={async e=>{e.preventDefault();if(await act({action:'confirm2fa',code:e.target.code.value}))SEC('')}}><p>Adicione esta chave ao seu autenticador e confirme o código:</p><code className="secret">{secret}</code><label>Código de 6 dígitos<input name="code" pattern="[0-9]{6}" required/></label><button className="primary" disabled={busy}>Confirmar ativação</button></form>}{security?.twoFactor&&<form className="space-top" onSubmit={e=>{e.preventDefault();act({action:'disable2fa',...Object.fromEntries(new FormData(e.target))})}}><label>Senha atual<input type="password" name="current" required autoComplete="current-password"/></label><label>Código do autenticador<input name="code" pattern="[0-9]{6}" required/></label><button className="secondary" disabled={busy}>Desativar 2FA</button></form>}</section><section className="panel padded"><h2>Alterar senha</h2><form onSubmit={async e=>{e.preventDefault();let form=e.target;if(await act({action:'password',...Object.fromEntries(new FormData(form))}))form.reset()}}><label>Senha atual<input name="current" type="password" required autoComplete="current-password"/></label><label>Nova senha<input name="password" type="password" minLength={12} required autoComplete="new-password" placeholder="Pelo menos 12 caracteres"/></label><button className="primary" disabled={busy}>Atualizar senha</button></form></section><section className="panel padded"><h2>Sessões ativas</h2><p>Sessões expiram automaticamente após 8 horas.</p>{security?.sessions.map((s,i)=><div className="session-row" key={i}><Icon name="lock" size={18}/><div><strong>{s.current?'Este dispositivo':'Outro dispositivo'}</strong><small>{s.ip} · {fmt(s.created)}</small></div><Badge>{s.current?'Atual':'Ativa'}</Badge></div>)}<button className="secondary" disabled={busy} onClick={()=>act({action:'revoke'})}>Encerrar outras sessões</button></section>{user.role==='Administrador'&&<section className="panel padded"><h2>Backup do banco de dados</h2><p>Backup automático diário enquanto o servidor está ativo. Retenção dos 30 arquivos mais recentes.</p><p>Último backup: {security?.lastBackup?new Date(security.lastBackup).toLocaleString('pt-BR'):'Ainda não realizado'}</p><button className="secondary" onClick={async()=>{try{await api('backup','POST');await load();notify('Backup criado no servidor.')}catch(e){notify(e.message)}}}>Criar backup agora</button><small className="block">A chave do cofre deve ser preservada separadamente, conforme o README.</small></section>}<section className="panel padded"><h2>Integrações</h2><p>O assistente aceita um provedor compatível com Chat Completions configurado no servidor. GitHub, GitLab e deploy automatizado permanecem como integrações futuras do briefing.</p><div className="row wrap"><Badge type="purple">API de IA configurável</Badge><Badge type="amber">Git não conectado</Badge></div><small className="block">Consulte as variáveis de ambiente no README do projeto.</small></section></div>}
